import pytest
from marshmallow import Schema, fields, ValidationError

def test_meta_many():
    class MySchema(Schema):
        field = fields.String()

        class Meta:
            many = True

    schema = MySchema()
    assert schema.many is True

    data = schema.load([{"field": "value"}])
    assert data == [{"field": "value"}]

    dumped = schema.dump([{"field": "value"}])
    assert dumped == [{"field": "value"}]

def test_meta_many_explicit_override():
    class MySchema(Schema):
        field = fields.String()

        class Meta:
            many = True

    schema = MySchema(many=False)
    assert schema.many is False
    data = schema.load({"field": "value"})
    assert data == {"field": "value"}
